package owl.nh;
import java.util.*;
import java.nio.file.*;
public final class OlmRaidFinishTests {
 static void check(boolean ok,String message){CoreTests.check(ok,"Olm raid finish: "+message);}
 public static void main(String[] args)throws Exception{
  OlmRaidFinish flow=new OlmRaidFinish();check(!flow.active(),"no post-fight actions before head death");flow.start(10);check(flow.stage==OlmRaidFinish.Stage.CHEST,"head death begins chest stage");Map<Integer,Integer> inventory=new HashMap<>();inventory.put(20984,2);flow.chestRequested(12,inventory);check(!flow.observeLoot(13,inventory)&&!flow.emptyRewardsObserved(true,true),"a chest click or an empty window alone cannot confirm collection");flow.rewardRequested(13,inventory,100);inventory.put(100,1);check(flow.observeLoot(14,inventory)&&!flow.emptyRewardsObserved(true,false),"first item gain does not leave other rewards behind");check(!flow.emptyRewardsObserved(false,true),"a hidden window does not prove chest empty");check(flow.emptyRewardsObserved(true,true)&&flow.stage==OlmRaidFinish.Stage.EXIT,"observed inventory gain and empty visible rewards permit exit");check(!flow.exited(true)&&flow.exited(false)&&!flow.active(),"exit needs an observed departure");flow.reset();flow.start(30);check(flow.timedOut(230),"ignored actions eventually save and stop");
  check("Climb-up".equals(OlmRaidFinish.objectAction(false,-1,1,"Steps",new String[]{"Climb-up"})),"nearby steps use the real available exit action");check(OlmRaidFinish.objectAction(false,-1,2,"Olm gate",new String[]{"Pass"})==null,"do not reuse the fight gate as an exit guess");check("Search".equals(OlmRaidFinish.objectAction(true,-1,3,"Reward chest",new String[]{"Search"})),"use visible chest action");check(OlmRaidFinish.objectAction(true,10,3,"Reward chest",new String[]{"Search"})==null,"explicit chest ID restricts discovery");
  Path temporary=Files.createTempDirectory("olm-profile-test-");try{String json=new String(Files.readAllBytes(CombatRuntime.projectRoot().toPath().resolve("profiles/olm-demo2-candidate.json")),java.nio.charset.StandardCharsets.UTF_8);com.google.gson.JsonObject data=new com.google.gson.JsonParser().parse(json).getAsJsonObject();data.addProperty("schema",OlmPresetStore.SCHEMA);if(!data.has("observedGear"))data.add("observedGear",new com.google.gson.JsonObject());Path saved=OlmPresetStore.saveProfile(temporary,data.toString());check(OlmPresetStore.parse(OlmAttemptStore.read(saved))!=null,"profile saves and reloads without a completed raid");String before=OlmAttemptStore.read(saved);boolean invalid=false;try{OlmPresetStore.saveProfile(temporary,"{}");}catch(RuntimeException expected){invalid=true;}check(invalid&&before.equals(OlmAttemptStore.read(saved)),"invalid replacement preserves the saved profile");try(java.util.stream.Stream<Path> files=Files.list(saved.getParent())){check(files.count()==1,"profile write cleans temporary files");}}finally{try(java.util.stream.Stream<Path> files=Files.walk(temporary)){files.sorted(Comparator.reverseOrder()).forEach(p->{try{Files.delete(p);}catch(Exception e){throw new RuntimeException(e);}});}}
  restockChecks(); bankPresetChecks(); doorRecoveryChecks(); productionCollection();
  System.out.println("Olm raid finish checks passed: chest acknowledgement, all rewards, exit evidence, timeout and reusable profile persistence. Synthetic only.");
 }
 private static void restockChecks(){
  OlmRestock r=new OlmRestock();r.start(10,100L,1000);check(r.waiting(1000000099L),"does not bank before sampled delay");check(!r.waiting(1000000100L)&&r.stage==OlmRestock.Stage.BANK,"banks when delay elapses without sleeping");boolean invalid=false;try{r.start(10,0,5001);}catch(IllegalArgumentException expected){invalid=true;}check(invalid,"delay is bounded to five seconds");
  Map<Integer,Integer> baseline=new HashMap<>();baseline.put(1,4);baseline.put(-2,1);r.requested(11,Collections.emptyMap());check(!r.loaded(12,Collections.singletonMap(1,4),baseline),"missing equipment cannot confirm preset");check(!r.loaded(12,baseline,baseline)&&!r.loaded(12,baseline,baseline),"click or same-tick snapshot cannot confirm load");check(r.loaded(13,baseline,baseline),"exact starting quantities and equipment stable across ticks confirm load");r.doorRequested(14,1,false);check(!r.entered(1,false)&&r.entered(1,true),"door click waits for actual area transition");check(OlmRestock.matches(true,"Bank chest",new String[]{"Use","Last-preset"})&&!OlmRestock.matches(true,"Reward chest",new String[]{"Last-preset"}),"only the correct bank object action is used");check(OlmRestock.matches(false,"Chambers of Xeric",new String[]{"Enter"}),"outside entry uses the supplied door action");r.reset();check(r.stage==OlmRestock.Stage.IDLE,"new runs clear post-raid state");
 } private static void doorRecoveryChecks(){OlmRestock r=new OlmRestock();r.doorRequested(10,1,false);check(!r.retryDoor(14,false)&&!r.retryDoor(15,true),"entry requests wait five ticks and never repeat while walking");check(r.retryDoor(15,false)&&r.stage==OlmRestock.Stage.DOOR,"ignored stationary entry permits retry");r.doorRequested(15,1,false);check(!r.entered(1,false),"repeated click is never entry confirmation");r.retryDoor(20,false);r.doorRequested(20,1,false);check(!r.retryDoor(25,false)&&r.doorFailed(25,false),"three unconfirmed requests end with a visible error rather than infinite waiting");check(r.entered(2,true),"actual area transition completes entry after retry");check(OlmRestock.matches(false,"Chambers of Xeric",new String[]{null,"Enter"}),"available Enter action need not be at index zero");Map<Integer,Integer> expected=new HashMap<>(),current=new HashMap<>();expected.put(10,4);expected.put(-20,1);current.put(10,3);current.put(-20,1);List<Map<String,Integer>> d=OlmRestock.differences(current,expected);check(d.size()==1&&d.get(0).get("itemId")==10&&d.get(0).get("expected")==4&&d.get(0).get("observed")==3,"preset blocker identifies exact missing quantity without weakening verification");} private static void bankPresetChecks(){check(OlmBankPresetView.cox("<img=1><col=ff0000>Cox</col>",null),"recognize exact native Cox label despite icon/colour markup");check(!OlmBankPresetView.cox("Cox backup",null),"do not silently load a different preset");check(OlmBankPresetView.manager(null,null,new String[]{"Preset Manager"}),"identify the actual preset manager action");Map<String,Object> values=new HashMap<>();values.put("getOption","Load");values.put("getTarget","<img=1>Cox");values.put("getParam1",123);net.runelite.api.MenuEntry e=ChambersTests.fake(net.runelite.api.MenuEntry.class,values);check(OlmBankPresetView.loadEntry(e,123)&&!OlmBankPresetView.loadEntry(e,124),"load menu must belong to Cox widget");values.put("getOption","Overwrite");check(!OlmBankPresetView.loadEntry(e,123),"never select overwrite, delete or default actions");} private static void productionCollection()throws Exception{
  String json=Files.readString(CombatRuntime.projectRoot().toPath().resolve("profiles/olm-demo2-candidate.json"),java.nio.charset.StandardCharsets.UTF_8);com.google.gson.JsonObject setup=new com.google.gson.JsonParser().parse(json).getAsJsonObject();setup.addProperty("schema",OlmPresetStore.SCHEMA);if(!setup.has("observedGear"))setup.add("observedGear",new com.google.gson.JsonObject());setup.getAsJsonArray("chamberRegions").add(12850);
  Map<String,Object> actor=new HashMap<>();actor.put("getLocalLocation",new net.runelite.api.coords.LocalPoint(128,128));actor.put("getWorldLocation",new net.runelite.api.coords.WorldPoint(3201,3201,0));net.runelite.api.Player player=ChambersTests.fake(net.runelite.api.Player.class,actor);
  Map<String,Object> rewardFields=new HashMap<>();rewardFields.put("isVisible",true);rewardFields.put("getId",35323909);rewardFields.put("getActions",new String[]{"Close"});rewardFields.put("getBounds",new java.awt.Rectangle(100,100,25,25));net.runelite.api.widgets.Widget container=ChambersTests.fake(net.runelite.api.widgets.Widget.class,rewardFields);Map<String,Object> slotFields=new HashMap<>();slotFields.put("isVisible",true);slotFields.put("getParent",container);slotFields.put("getItemId",566);slotFields.put("getItemQuantity",10);slotFields.put("getBounds",new java.awt.Rectangle(100,100,25,25));rewardFields.put("getDynamicChildren",new net.runelite.api.widgets.Widget[]{ChambersTests.fake(net.runelite.api.widgets.Widget.class,slotFields)});
  Map<String,Object> bagFields=new HashMap<>();bagFields.put("getItems",new net.runelite.api.Item[0]);net.runelite.api.ItemContainer bag=ChambersTests.fake(net.runelite.api.ItemContainer.class,bagFields);
  java.awt.Canvas canvas=new java.awt.Canvas(){public boolean isFocusOwner(){return true;}};canvas.setSize(800,600);Map<String,Object> fields=new HashMap<>();fields.put("isClientThread",true);fields.put("getGameState",net.runelite.api.GameState.LOGGED_IN);fields.put("getLocalPlayer",player);fields.put("getCanvas",canvas);fields.put("getNpcs",Collections.emptyList());fields.put("getPlayers",Collections.emptyList());fields.put("getPlayerOptions",new String[0]);fields.put("getBoostedSkillLevel",99);fields.put("getRealSkillLevel",99);fields.put("getBaseX",3200);fields.put("getBaseY",3200);fields.put("getTickCount",10);fields.put("getGameCycle",100);fields.put("getWidget",container);fields.put("getItemContainer",bag);
  net.runelite.api.Client client=ChambersTests.fake(net.runelite.api.Client.class,fields);java.lang.reflect.Constructor<net.runelite.client.callback.ClientThread> ctor=net.runelite.client.callback.ClientThread.class.getDeclaredConstructor(net.runelite.api.Client.class);ctor.setAccessible(true);CombatRuntime runtime=new CombatRuntime(client,ctor.newInstance(client),new net.runelite.client.eventbus.EventBus(),null);Path temp=Files.createTempDirectory("olm-finish-runtime-");runtime.olm.attemptRoot=temp;
  try{runtime.olm.loadPreset(setup.toString());runtime.olm.startMain();runtime.olm.manualPhase(3);Map<String,Object> head=new HashMap<>();head.put("getId",7554);runtime.olm.actorDeath(ChambersTests.fake(net.runelite.api.NPC.class,head));runtime.olm.tick(true);check(runtime.olm.running&&runtime.olm.status.contains("Collecting a visible chest reward"),"production handler clicks the recorded visible reward slot after head death");bagFields.put("getItems",new net.runelite.api.Item[]{new net.runelite.api.Item(566,10)});rewardFields.put("getDynamicChildren",new net.runelite.api.widgets.Widget[0]);fields.put("getTickCount",11);fields.put("getGameCycle",130);runtime.olm.tick(true);check(runtime.olm.running&&runtime.olm.status.contains("stable empty"),"inventory acknowledgement waits for a stable empty reward container");fields.put("getGameCycle",160);fields.put("getTickCount",12);runtime.olm.tick(true);check(runtime.olm.status.contains("empty reward window"),"two observed empty ticks advance to closing rewards");fields.put("getBaseX",6400);fields.put("getGameCycle",190);fields.put("getTickCount",13);runtime.olm.tick(true);check(runtime.olm.running&&runtime.olm.status.contains("sampled 1-5 seconds"),"observed departure starts delayed restock without starting another fight");OlmLearningTests.awaitSave(runtime.olm);com.google.gson.JsonObject saved=new com.google.gson.JsonParser().parse(OlmAttemptStore.latest(temp)).getAsJsonObject();check(saved.getAsJsonObject("runExperience").get("lootConfirmed").getAsBoolean()&&saved.getAsJsonObject("attempt").get("outcome").getAsString().equals("LOOTED_EXITED"),"production terminal checkpoint records loot and exit separately from head death");}
  finally{runtime.olm.close();OlmLearningTests.awaitSave(runtime.olm);try(java.util.stream.Stream<Path> files=Files.walk(temp)){files.sorted(Comparator.reverseOrder()).forEach(p->{try{Files.delete(p);}catch(Exception e){throw new RuntimeException(e);}});}}
 }
}



